package com.damagehistory;

import static com.damagehistory.PredictedHit.AttackStyle.CASTING;
import static com.damagehistory.PredictedHit.AttackStyle.DEFENSIVE_CASTING;
import static com.damagehistory.PredictedHit.AttackStyle.RANGING;
import static net.runelite.api.gameval.VarbitID.AUTOCAST_SET;

import com.damagehistory.panel.DamageHistoryPanel;
import com.damagehistory.panel.PlayerHitRecord;
import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PartyChanged;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
        name = "Damage History"
)
public class DamageHistoryPlugin extends Plugin {

    private static final String CXD_PLUGIN_NAMESPACE = "customizable-xp-drops";
    private static final String PREDICTED_HIT_MESSAGE = "predicted-hit";
    private static final String CONFIG_GROUP = "DamageHistory";
    private static final int DEFAULT_ATTACK_SPEED = 4;

    private static final Set<Integer> NPC_BLOCKLIST = Set.of(
            NpcID.CRYSTAL_HUNLLEF_MELEE,
            NpcID.CRYSTAL_HUNLLEF_RANGED,
            NpcID.CRYSTAL_HUNLLEF_MAGIC,
            NpcID.CRYSTAL_HUNLLEF_MELEE_HM,
            NpcID.CRYSTAL_HUNLLEF_RANGED_HM,
            NpcID.CRYSTAL_HUNLLEF_MAGIC_HM
    );

    // Currently this points to DEADMAN_THRALL_GHOSTLY_GREATER_WISP
    private static final int HIGHEST_ALLOWED_NPC_ID = 15571;

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private DamageHistoryConfig config;

    @Inject
    private EventBus eventBus;

    @Inject
    private Gson gson;

    @Inject
    private ItemManager itemManager;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private PartyService partyService;

    @Inject
    private WSClient wsClient;

    private DamageHistoryPanel panel;
    private NavigationButton navButton;
    private final BufferedImage icon = ImageUtil.loadImageResource(DamageHistoryPlugin.class, "panel-icon.png");
    private boolean isAutoCasting;
    private boolean isManualCasting;

    @Override
    protected void startUp() throws Exception {
        panel = injector.getInstance(DamageHistoryPanel.class);

        navButton = NavigationButton.builder()
                .tooltip("Damage History")
                .icon(icon)
                .priority(5)
                .panel(panel)
                .build();

        clientToolbar.addNavigation(navButton);

        try {
            wsClient.registerMessage(DamageHistoryPartyMessage.class);
        } catch (Exception e) {
            log.error("Failed to register party message", e);
        }

        log.debug("Damage History started!");
    }

    @Override
    protected void shutDown() throws Exception {
        clientToolbar.removeNavigation(navButton);
        panel = null;
        log.debug("Damage History stopped!");
    }

    @Subscribe
    public void onPluginMessage(PluginMessage pluginMessage) {
        if (!CXD_PLUGIN_NAMESPACE.equals(pluginMessage.getNamespace()) ||
            !PREDICTED_HIT_MESSAGE.equals(pluginMessage.getName())) {
            return;
        }

        Map<String, Object> data = pluginMessage.getData();
        Object json = data.get("value");

        log.debug(json.toString());

        PredictedHit predictedHit = gson.fromJson(json.toString(), PredictedHit.class);
        String playerName = client.getLocalPlayer().getName();
        int currentTick = client.getTickCount();
        processPredictedHit(predictedHit, playerName, currentTick);

        if (config.sendDamageHistoryOverParty() && partyService.isInParty()) {
            partyService.send(new DamageHistoryPartyMessage(predictedHit, playerName, currentTick));
        }
    }

    private void processPredictedHit(PredictedHit predictedHit, String playerName, int serverTick) {
        // Skip PvP hits and invalid NPCs
        if (predictedHit.isOpponentIsPlayer() || predictedHit.getNpcId() == -1) {
            return;
        }

        // Ignore blocked NPCs
        if (NPC_BLOCKLIST.contains(predictedHit.getNpcId())) {
            return;
        }

        // Ignore new NPCs to avoid abuse for new content
        if (predictedHit.getNpcId() > HIGHEST_ALLOWED_NPC_ID) {
            return;
        }

        int weaponId = predictedHit.getEquippedWeaponId();
        String weaponName = itemManager.getItemComposition(predictedHit.getEquippedWeaponId()).getMembersName();
        int hit = predictedHit.getHit();
        String npcName = client.getNpcDefinition(predictedHit.getNpcId()).getName();

        int attackSpeed = determineAttackSpeed(weaponId, predictedHit.getAttackStyle());
        // Manual casting only lasts one attack max per click
        isManualCasting = false;

        boolean specialAttack = predictedHit.isSpecialAttack();

        log.debug("{} hit {} on {}", weaponName, hit, npcName);

        if (panel != null) {
            // Get the previous hit for this player to calculate tick delay
            PlayerHitRecord previousHit = panel.getLatestHitForPlayer(playerName);

            Integer ticksSincePrevious = null;
            Integer previousAttackSpeed = null;

            if (previousHit != null) {
                ticksSincePrevious = serverTick - previousHit.getTickCount();
                previousAttackSpeed = previousHit.getAttackSpeed();
            }

            PlayerHitRecord record = new PlayerHitRecord(
                    playerName,
                    hit,
                    npcName,
                    weaponId,
                    serverTick,
                    attackSpeed,
                    specialAttack,
                    ticksSincePrevious,
                    previousAttackSpeed
            );
            log.debug(record.toString());
            SwingUtilities.invokeLater(() -> {
                panel.addHit(record);
            });
        }
    }

    @Subscribe
    public void onDamageHistoryPartyMessage(DamageHistoryPartyMessage damageHistoryPartyMessage) {
        // Ignore incoming party messages from local player, since those are already handled.
        if (client.getLocalPlayer() != null && client.getLocalPlayer().getName() != null &&
            client.getLocalPlayer().getName().equals(damageHistoryPartyMessage.getPlayerName())) {
            return;
        }

        clientThread.invoke(() -> processPredictedHit(
                damageHistoryPartyMessage.getPredictedHit(),
                damageHistoryPartyMessage.getPlayerName(),
                damageHistoryPartyMessage.getServerTick())
        );
    }

    @Subscribe
    public void onPartyChanged(PartyChanged partyChanged) {
        if (panel != null && config.clearOnPartyChange()) {
            SwingUtilities.invokeLater(() -> panel.clearOtherPlayers());
        }
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event) {
        if ("Cast".equals(event.getMenuOption()) && event.getMenuAction() == MenuAction.WIDGET_TARGET_ON_NPC) {
            isManualCasting = true;
        } else {
            isManualCasting = false;
        }
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged varbitChanged) {
        if (varbitChanged.getVarbitId() == AUTOCAST_SET) {
            isAutoCasting = varbitChanged.getValue() == 1;
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged configChanged) {
        if (CONFIG_GROUP.equals(configChanged.getGroup()) && panel != null) {
            log.debug("Config changed: {} = {}", configChanged.getKey(), configChanged.getNewValue());
            SwingUtilities.invokeLater(() -> panel.refreshPanel());
        }
    }

    @Provides
    DamageHistoryConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(DamageHistoryConfig.class);
    }

    private boolean isAutoCastingMage(PredictedHit.AttackStyle attackStyle) {
        boolean hasMageWeapon = attackStyle == CASTING || attackStyle == DEFENSIVE_CASTING;
        return hasMageWeapon && isAutoCasting;
    }

    private int determineAttackSpeed(int weaponId, PredictedHit.AttackStyle attackStyle) {
        if (weaponId == -1) {
            return DEFAULT_ATTACK_SPEED;
        }

        if (isManualCasting) {
            return 5;
        }

        if (isAutoCastingMage(attackStyle)) {
            if (weaponId == ItemID.NIGHTMARE_STAFF_HARMONISED) {
                return 4;
            } else {
                return 5;
            }
        }

        ItemStats itemStats = itemManager.getItemStats(weaponId);
        int attackSpeed = itemStats != null ? itemStats.getEquipment().getAspeed() : DEFAULT_ATTACK_SPEED;

        // Both Accurate and Rapid are reported as RANGING, but assume the player is playing on Rapid, which attacks
        // one tick faster.
        if (attackStyle == RANGING) {
            attackSpeed -= 1;
        }

        return attackSpeed;
    }
}

package com.damagehistory;

import lombok.Data;
import net.runelite.api.Prayer;

@Data
public class PredictedHit {

    public enum AttackStyle {
        NONE,
        ACCURATE,
        AGGRESSIVE,
        DEFENSIVE,
        CONTROLLED,
        RANGING,
        LONGRANGE,
        CASTING,
        DEFENSIVE_CASTING,
        OTHER,
    }

    public enum Raid {
        NONE,
        COX,
        COX_CM,
        TOB,
        TOA,
    }

    // Calculated with (int) Math.round((hpXpAwarded * (3.0d / 4.0d)) / xpModifier / userXpModifier)
    private int hit = -1;

    private int hpXpAwarded = -1;

    private boolean opponentIsPlayer = false;
    // If opponentIsPlayer is true this is -1
    private int npcId = -1;

    // If opponentIsPlayer is false this is -1
    private int playerCombatLevel = -1;

    private int equippedWeaponId = -1;
    private AttackStyle attackStyle = AttackStyle.NONE;
    private Prayer[] activePrayer = new Prayer[0];
    private boolean specialAttack = false;

    // user defined xp modifier in the Customizable-xp-drops plugin
    private double userXpModifier = -1;

    // Final xp modifier used to calculate hit
    private double xpModifier = -1;

    private Raid raid = Raid.NONE;
    // -1 if Raid is NONE
    private int partySize = -1;
    // -1 if Raid is not TOA
    private int raidLevel = -1;
    // -1 if Raid is not TOA
    private int raidRoomLevel = -1;
}

package com.damagehistory.panel;

import com.damagehistory.DamageHistoryConfig;
import java.awt.*;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import lombok.Setter;
import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;
import net.runelite.client.party.PartyService;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

@Singleton
public class DamageHistoryPanel extends PluginPanel {

    @Inject
    private ItemManager itemManager;

    @Inject
    private DamageHistoryConfig config;

    @Inject
    @Setter
    private Client client;

    @Inject
    @Setter
    private PartyService partyService;

    private final JPanel basePanel = new JPanel();
    private final Map<String, PlayerPanel> playerPanels = new HashMap<>();

    public DamageHistoryPanel() {
        super(false);
        setLayout(new BorderLayout());

        basePanel.setBorder(new EmptyBorder(BORDER_OFFSET, BORDER_OFFSET, BORDER_OFFSET, BORDER_OFFSET));
        basePanel.setLayout(new net.runelite.client.ui.DynamicGridLayout(0, 1, 0, 5));

        final JPanel topPanel = new JPanel();
        topPanel.setBorder(new EmptyBorder(BORDER_OFFSET, 2, BORDER_OFFSET, 2));
        topPanel.setLayout(new BoxLayout(topPanel, BoxLayout.Y_AXIS));

        JPanel buttonPanel = new JPanel(new BorderLayout());
        buttonPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JLabel titleLabel = new JLabel("Damage History");
        titleLabel.setForeground(Color.WHITE);
        titleLabel.setBorder(new EmptyBorder(0, 8, 0, 0));
        buttonPanel.add(titleLabel, BorderLayout.WEST);

        JButton clearButton = new JButton("Clear History");
        clearButton.addActionListener(e -> clearHistory());
        buttonPanel.add(clearButton, BorderLayout.EAST);
        buttonPanel.setBorder(new EmptyBorder(0, 0, 8, 0));
        topPanel.add(buttonPanel);

        add(topPanel, BorderLayout.NORTH);

        // Wrap content to anchor to top and prevent expansion
        final JPanel northPanel = new JPanel(new BorderLayout());
        northPanel.add(basePanel, BorderLayout.NORTH);
        final JScrollPane scrollPane = new JScrollPane(northPanel);
        scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);

        add(scrollPane, BorderLayout.CENTER);

        checkEmpty();
        basePanel.revalidate();
        basePanel.repaint();
    }

    public PlayerHitRecord getLatestHitForPlayer(String playerName) {
        PlayerPanel playerPanel = playerPanels.get(playerName);
        return playerPanel != null ? playerPanel.getLatestHit() : null;
    }

    public PlayerPanel getPlayerPanel(String playerName) {
        return playerPanels.get(playerName);
    }

    public void addHit(PlayerHitRecord record) {
        // Remove empty message if it exists
        if (playerPanels.isEmpty()) {
            basePanel.removeAll();
        }

        PlayerPanel playerPanel = playerPanels.get(record.getPlayerName());
        if (playerPanel == null) {
            playerPanel = new PlayerPanel(record.getPlayerName(), itemManager, config, client, this);
            playerPanels.put(record.getPlayerName(), playerPanel);

            // Add local player at the top, others at the end
            if (client.getLocalPlayer() != null && client.getLocalPlayer().getName().equals(record.getPlayerName())) {
                basePanel.add(playerPanel, 0);
            } else {
                basePanel.add(playerPanel);
            }
            basePanel.revalidate();
        }

        playerPanel.addHit(record);
    }

    public void removePlayerPanel(String playerName) {
        PlayerPanel panel = playerPanels.remove(playerName);
        if (panel != null) {
            basePanel.remove(panel);
        }

        checkEmpty();

        basePanel.revalidate();
        basePanel.repaint();
    }

    public void clearOtherPlayers() {
        String localPlayerName = client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : null;
        playerPanels.entrySet().removeIf(entry -> {
            if (!entry.getKey().equals(localPlayerName)) {
                basePanel.remove(entry.getValue());
                return true;
            }
            return false;
        });
        checkEmpty();
        basePanel.revalidate();
        basePanel.repaint();
    }



    public void refreshPanel() {
        for (PlayerPanel playerPanel : playerPanels.values()) {
            playerPanel.refreshPanel();
        }
        basePanel.revalidate();
        basePanel.repaint();
    }

    private void checkEmpty() {
        if (!playerPanels.isEmpty()) {
            return;
        }

        basePanel.removeAll();
        JPanel emptyPanel = new JPanel(new BorderLayout());
        emptyPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JTextPane emptyText = new JTextPane();
        emptyText.setContentType("text/html");
        emptyText.setText("<html><div style='text-align: center;'>" +
                          "The <span style='color: #00FF00;'>Customizable XP Drops</span> plugin is required for populating data.<br><br>" +
                          "If you're not seeing any data here after hitting monsters, " +
                          "please go install it from the Plugin Hub.<br><br>" +
                          "If you don't want the customized xp drops, but still want this plugin's functionality, " +
                          "you can uncheck <span style='color: #FF0000;'>\"Use Customizable XP drops\"</span> from that plugin" +
                          "</div></html>");
        emptyText.setForeground(Color.WHITE);
        emptyText.setBackground(ColorScheme.DARK_GRAY_COLOR);
        emptyText.setEditable(false);
        emptyText.setBorder(new EmptyBorder(5, 5, 5, 5));
        emptyText.setPreferredSize(new Dimension(200, 300));

        emptyPanel.add(emptyText, BorderLayout.CENTER);
        basePanel.add(emptyPanel);
    }

    private void clearHistory() {
        for (PlayerPanel panel : playerPanels.values()) {
            basePanel.remove(panel);
        }
        playerPanels.clear();
        basePanel.removeAll();
        checkEmpty();
        basePanel.revalidate();
        basePanel.repaint();
    }


}

